import {sampleTimeline,validTimeline} from './blueprint-model.js';
export function attributeCalculationOrder(attributes){
 const byName=new Map(attributes.map(row=>[row.name,row])),state=new Map(),order=[];
 for(const name of byName.keys()){if(state.get(name)===2)continue;const stack=[{name,entered:false}];while(stack.length){const at=stack.at(-1),row=byName.get(at.name);if(!row)throw Error('계산 원본 속성이 없어요: '+at.name);if(!at.entered){state.set(at.name,1);at.entered=true;const source=row.calculation?.attribute;if(source){if(state.get(source)===1)throw Object.assign(Error('속성 계산 순환: '+[...stack.slice(-8).map(v=>v.name),source].join(' → ')),{code:'ATTRIBUTE_CALCULATION_CYCLE'});if(state.get(source)!==2){stack.push({name:source,entered:false});continue;}}}state.set(at.name,2);order.push(at.name);stack.pop();}}
 return order;
}
export async function resolveAttributeCurves(attributes,read,{capture=true,curves=Object.create(null)}={}){for(const row of attributes){const c=row.calculation;if(!c?.curve)continue;if(!Object.hasOwn(curves,c.curve)){const source=await read(c.curve),d=capture?structuredClone(source):source;if(d?.version!==1||!validTimeline(d.timeline))throw Error('계산 커브 검증 실패: '+c.curve);curves[c.curve]=d;}if(!curves[c.curve].timeline.tracks.some(t=>t.id===c.track&&t.type==='float'))throw Error('계산에 사용할 실수 커브 트랙이 없어요: '+c.curve+' #'+c.track);}return curves;}
export function calculatedAttributeBase(calculation,source,curves){let value=calculation.policy==='base'?source.base:calculation.policy==='bonus'?source.current-source.base:source.current;if(calculation.curve){const track=curves[calculation.curve]?.timeline.tracks.find(t=>t.id===calculation.track);if(!track)throw Error('계산 커브 트랙이 없어요.');value=sampleTimeline(track,value);}const result=calculation.coefficient*(calculation.preAdd+value)+calculation.postAdd;if(!Number.isFinite(result)||Math.abs(result)>1e9)throw Error('종속 속성 계산 범위 초과');return result;}
